def find_Min(arr, low, high):
    # Base case: if the array is not rotated
    if high < low:
        return arr[0]

    # Base case: if the array has only one element
    if low == high:
        return arr[low]

    # Find the middle element
    mid = low + (high - low) // 2

    # Check if the middle element is the minimum
    if mid > 0 and arr[mid] < arr[mid - 1]:
        return arr[mid]

    # If the middle element is greater than the next element, the middle element is not the minimum
    if mid > 0 and arr[mid - 1] < arr[mid]:
        return find_Min(arr, low, mid - 1)

    # Otherwise, the middle element is in the right half
    return find_Min(arr, mid + 1, high)

